local a={}function a.wrap360(b)b=b%360;if b<0 then b=b+360 end;return b end;function a.angleDelta(c,d)local e=a.wrap360(c-d)if e>180 then e=e-360 end;return e end;function a.absolute(f,g)if type(f)~="number"then return nil end;g=g==-1 and-1 or 1;return a.wrap360(f*g)end;local h={"N","NNE","NE","ENE","E","ESE","SE","SSE","S","SSW","SW","WSW","W","WNW","NW","NNW"}function a.compass(b)if type(b)~="number"then return"--"end;local i=math.floor(a.wrap360(b)/22.5+0.5)%16;return h[i+1]end;function a.calibrateSign(j,k,l)if type(j)~="number"or type(k)~="number"then return nil end;local m=a.angleDelta(k,j)if m==0 then return nil end;local n=l~=false;local o=m>0;return o==n and 1 or-1 end;return a